package main

// entry is a node in the cache's intrusive doubly linked recency list.
// Links are indices into Cache.entries; index 0 is the list sentinel.
type entry struct {
	key, value string
	prev, next int32
}

// Cache is a fixed-capacity least-recently-used cache of string keys and
// values. All operations run in O(1) expected time.
//
// Entries live in a single slice and are linked by index, which keeps
// allocations and GC pressure low for large caches. Slots freed by DEL are
// reused via a free list.
type Cache struct {
	capacity int
	index    map[string]int32
	entries  []entry // entries[0] is the sentinel: next is MRU, prev is LRU
	free     []int32
}

// NewCache returns an empty cache that holds at most capacity keys.
func NewCache(capacity int) *Cache {
	hint := min(capacity+1, 1<<20)
	c := &Cache{
		capacity: capacity,
		index:    make(map[string]int32, hint),
		entries:  make([]entry, 1, hint+1),
	}
	return c
}

// Len reports the number of keys held.
func (c *Cache) Len() int { return len(c.index) }

// Get returns the value for key and marks it most recently used.
func (c *Cache) Get(key string) (string, bool) {
	i, ok := c.index[key]
	if !ok {
		return "", false
	}
	c.moveToFront(i)
	return c.entries[i].value, true
}

// Set inserts or overwrites key, marks it most recently used, and evicts the
// least recently used key if the cache exceeds its capacity.
func (c *Cache) Set(key, value string) {
	if i, ok := c.index[key]; ok {
		c.entries[i].value = value
		c.moveToFront(i)
		return
	}
	if len(c.index) >= c.capacity {
		lru := c.entries[0].prev
		// Reuse the evicted slot directly for the new entry.
		delete(c.index, c.entries[lru].key)
		c.unlink(lru)
		c.entries[lru].key, c.entries[lru].value = key, value
		c.pushFront(lru)
		c.index[key] = lru
		return
	}
	i := c.alloc(key, value)
	c.pushFront(i)
	c.index[key] = i
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key string) bool {
	i, ok := c.index[key]
	if !ok {
		return false
	}
	delete(c.index, key)
	c.unlink(i)
	c.entries[i] = entry{}
	c.free = append(c.free, i)
	return true
}

func (c *Cache) alloc(key, value string) int32 {
	if n := len(c.free); n > 0 {
		i := c.free[n-1]
		c.free = c.free[:n-1]
		c.entries[i].key, c.entries[i].value = key, value
		return i
	}
	c.entries = append(c.entries, entry{key: key, value: value})
	return int32(len(c.entries) - 1)
}

func (c *Cache) unlink(i int32) {
	e := &c.entries[i]
	c.entries[e.prev].next = e.next
	c.entries[e.next].prev = e.prev
}

func (c *Cache) pushFront(i int32) {
	head := c.entries[0].next
	c.entries[i].prev, c.entries[i].next = 0, head
	c.entries[head].prev = i
	c.entries[0].next = i
}

func (c *Cache) moveToFront(i int32) {
	if c.entries[0].next == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

// Command app simulates an LRU cache. It reads a capacity followed by
// SET/GET/DEL/SIZE commands from standard input and writes results to
// standard output.
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "lru:", err)
		os.Exit(1)
	}
}

// run processes the full command stream from r, writing results to w.
func run(r io.Reader, w io.Writer) error {
	in := bufio.NewReaderSize(r, 1<<20)
	out := bufio.NewWriterSize(w, 1<<20)

	first, err := readLine(in)
	if first == nil && err != nil {
		if err == io.EOF {
			return nil
		}
		return err
	}
	capacity, perr := strconv.Atoi(string(bytes.TrimSpace(first)))
	if perr != nil {
		return fmt.Errorf("invalid capacity: %w", perr)
	}
	cache := NewCache(capacity)

	for err == nil {
		var line []byte
		line, err = readLine(in)
		if len(line) > 0 {
			execute(cache, out, line)
		}
	}
	if err != io.EOF {
		return err
	}
	return out.Flush()
}

// readLine returns the next line without its trailing "\n" or "\r\n".
// The returned slice is only valid until the next read.
func readLine(r *bufio.Reader) ([]byte, error) {
	line, err := r.ReadSlice('\n')
	if err == bufio.ErrBufferFull {
		// Rare: a line longer than the buffer. Accumulate it.
		buf := append([]byte(nil), line...)
		for err == bufio.ErrBufferFull {
			line, err = r.ReadSlice('\n')
			buf = append(buf, line...)
		}
		line = buf
	}
	if err == io.EOF && len(line) == 0 {
		return nil, io.EOF
	}
	line = bytes.TrimSuffix(line, []byte("\n"))
	line = bytes.TrimSuffix(line, []byte("\r"))
	return line, err
}

// execute runs a single command line against cache. Unknown commands are
// ignored.
func execute(cache *Cache, out *bufio.Writer, line []byte) {
	cmd, rest, _ := bytes.Cut(line, []byte(" "))
	switch string(cmd) {
	case "SET":
		key, value, _ := bytes.Cut(rest, []byte(" "))
		cache.Set(string(key), string(value))
	case "GET":
		// string(rest) in a map lookup does not allocate.
		if v, ok := cache.Get(string(rest)); ok {
			out.WriteString(v)
		} else {
			out.WriteString("NULL")
		}
		out.WriteByte('\n')
	case "DEL":
		if cache.Delete(string(rest)) {
			out.WriteString("1\n")
		} else {
			out.WriteString("0\n")
		}
	case "SIZE":
		out.Write(strconv.AppendInt(out.AvailableBuffer(), int64(cache.Len()), 10))
		out.WriteByte('\n')
	}
}
